import { chromium } from 'playwright';
const b=await chromium.launch({headless:true}); const p=await b.newPage();
await p.goto('http://127.0.0.1:60567/login'); await p.locator('input').nth(0).fill('ops@lab.test'); await p.locator('input').nth(1).fill('lab-ops-pass'); await p.getByRole('button',{name:'Sign in'}).click(); await p.getByText('Refunds',{exact:true}).click(); await p.waitForTimeout(500);
const done=[];
for(let pg=1;pg<=3;pg++){
 const rows=p.locator('table tbody tr');
 for(let i=0;i<await rows.count();i++){
  const row=rows.nth(i); const id=await row.getAttribute('data-id');
  const status=(await row.locator('td').nth(4).innerText()).trim(); if(status!=='Pending')continue;
  const blocked=await row.locator('.badge').filter({hasText:'Blocked'}).count()>0;
  const reason=(await row.locator('td').nth(2).innerText()).trim();
  const amountText=(await row.locator('td').nth(3).innerText()).trim(); const amount=Number(amountText.replace(/[^0-9]/g,''));
  let action=null; if(blocked)action='Reject'; else if(reason==='Damaged item'&&amount<=500)action='Approve';
  if(action){ await row.getByRole('button',{name:action,exact:true}).click(); await p.waitForTimeout(150); done.push(`${id} ${action}`); }
 }
 console.log('Page',pg,'rows',await rows.count());
 if(pg<3){ await p.getByRole('button',{name:'Next',exact:true}).click(); await p.waitForTimeout(300); }
}
console.log('Processed',done.join(', ')); console.log((await p.locator('body').innerText()).slice(-1000)); await b.close();
EOF
